// Prepare System Context & Payload for AI Models (OpenAI, Claude, or xAI Grok)
const body = $input.item.json.body || {};
const userMessage = body.message || '';
const context = body.context || {};

// System prompt pre-configured for Grok / LLMs
const systemPrompt = `You are Zen AI Copilot, an intelligent focus and productivity assistant for the Zenclox Pomodoro App.

Zenclox Features:
- Cinema Mode / Flow Shield (F key): Fullscreen distraction-blocking overlay.
- Themes: Void (violet default), Dark, Ocean (cyan/blue), Forge (amber), Light.
- Soundscapes: Rain 🌧️, Cosmic Space 🌌, Fire 🔥, Binaural Beats 🎧.
- Presets: 25/5 classic, 50/10 deep, 90/20 ultra, Box Breathing prep (1 min).
- Session DNA Strand (3D Helix), Zen Mode (Z key), Command Palette (Ctrl+K).

Output JSON Schema Requirement:
You MUST respond with raw JSON matching this structure:
{
  "reply": "Your Markdown answer here",
  "actions": [
    {"label": "🛡️ Toggle Cinema Mode", "type": "toggle_shield"},
    {"label": "🌊 Switch to Ocean Theme", "type": "set_theme", "value": "ocean"},
    {"label": "⛈️ Storm Audio Preset", "type": "set_sound_preset", "preset": "storm"}
  ]
}

Current User App Context:
- Active Theme: ${context.theme || 'void'}
- Timer State: ${JSON.stringify(context.timer || {})}
- Session Intention: ${context.intention || 'None'}

User Question: ${userMessage}`;

return {
  json: {
    systemPrompt,
    userMessage,
    grokPayload: {
      model: "grok-2",
      messages: [
        { role: "system", content: systemPrompt },
        { role: "user", content: userMessage }
      ],
      temperature: 0.7
    }
  }
};

// Comprehensive AI Agent Logic Engine (Matching all Zenclox features)
const input = $input.item.json;
const msg = (input.userMessage || '').toLowerCase();

let reply = "I am your Zen AI Copilot. How can I assist your focus flow state today?";
let actions = [];

if (msg.includes('cinema') || msg.includes('shield') || msg.includes('overlay') || msg.includes('distraction')) {
  reply = "🎬 **Cinema Mode (Flow Shield)** creates a full-screen ambient overlay that blocks all visual distractions and dims background UI so you can focus entirely on the timer circle. Press **F** key or click below to toggle!";
  actions.push({ label: "🛡️ Toggle Cinema Mode", type: "toggle_shield" });
} else if (msg.includes('ocean') || msg.includes('theme') || msg.includes('color') || msg.includes('void') || msg.includes('forge')) {
  reply = "🎨 Zenclox features 5 curated color themes: 🟣 **Void** (Violet default), ⚫ **Dark** (Monochrome), 🌊 **Ocean** (Cyan/Blue), 🔥 **Forge** (Warm amber), and ☀️ **Light** (Daytime).";
  actions.push({ label: "🟣 Void Theme", type: "set_theme", value: "void" });
  actions.push({ label: "🌊 Ocean Theme", type: "set_theme", value: "ocean" });
  actions.push({ label: "🔥 Forge Theme", type: "set_theme", value: "forge" });
} else if (msg.includes('sound') || msg.includes('rain') || msg.includes('audio') || msg.includes('fire') || msg.includes('space') || msg.includes('binaural')) {
  reply = "🎧 Zenclox ambient soundscapes are synthesized live via Web Audio API: Rain 🌧️, Cosmic Space 🌌, Crackling Fire 🔥, and Focus Binaural Beats 🎧.";
  actions.push({ label: "⛈️ Storm Preset", type: "set_sound_preset", preset: "storm" });
  actions.push({ label: "🌌 Space Void Preset", type: "set_sound_preset", preset: "space" });
  actions.push({ label: "🔇 Mute All Sounds", type: "set_sound_preset", preset: "mute" });
} else if (msg.includes('timer') || msg.includes('focus') || msg.includes('start') || msg.includes('pomodoro')) {
  reply = "⏱️ Customize Focus/Break times or use quick presets: **25/5 Classic**, **50/10 Deep**, or **90/20 Ultra**. You can also enable Box Breathing prep before sessions.";
  actions.push({ label: "🧘 Start Box Breathing Prep", type: "start_breathing" });
  actions.push({ label: "⏱️ Start 25m Focus Timer", type: "start_timer", mins: 25 });
} else if (msg.includes('dna') || msg.includes('helix') || msg.includes('strand')) {
  reply = "🧬 The **Session DNA Strand** visualizes your session history as an interactive 3D double helix!";
  actions.push({ label: "🧬 View Session DNA", type: "open_dna" });
} else if (msg.includes('zen mode') || msg.includes('sanctuary')) {
  reply = "🧘 **Zen Mode** strips away UI distractions, leaving only the timer and soothing zen graphics.";
  actions.push({ label: "🧘 Toggle Zen Mode", type: "toggle_zen" });
} else {
  reply = `Got it! Running focus analysis for: "${input.userMessage}". Here are recommended quick actions:`;
  actions.push({ label: "🛡️ Toggle Cinema Mode", type: "toggle_shield" });
  actions.push({ label: "🌊 Ocean Theme", type: "set_theme", value: "ocean" });
  actions.push({ label: "⛈️ Storm Soundscape", type: "set_sound_preset", preset: "storm" });
}

return {
  json: {
    reply,
    actions
  }
};
